import { chromium } from "@playwright/test";
const browser = await chromium.launch();
const page = await browser.newPage();
await page.addInitScript(() => {
  document.documentElement.style.fontSize = "32px";
});
const widths = [360, 390, 430, 768, 1280];
const results = [];
for (const route of ["/", "/studio"]) {
  for (const width of widths) {
    await page.setViewportSize({ width, height: 900 });
    await page.goto(`http://127.0.0.1:4174${route}`, { waitUntil: "domcontentloaded" });
    const fit = await page.evaluate(() => {
      const view = document.documentElement.clientWidth;
      const worst = [...document.querySelectorAll("body *")].reduce((best, element) => {
        const rect = element.getBoundingClientRect();
        if (rect.right > best.right) {
          return { right: rect.right, width: rect.width, className: String(element.className).slice(0, 60), tag: element.tagName };
        }
        return best;
      }, { right: 0, width: 0, className: "", tag: "" });
      return {
        scroll: document.documentElement.scrollWidth,
        client: view,
        fits: document.documentElement.scrollWidth <= view + 1,
        worst,
      };
    });
    results.push({ route, width, ...fit });
  }
}
console.log(JSON.stringify(results, null, 2));
await browser.close();
EOF
